<?php
namespace app\service;
use think\facade\Db;
class GatewayCache{
 public static float $endpointRedisConnectMs=0.0; public static float $endpointRedisGetMs=0.0;
 private const EP_TTL=300; private const AUTH_TTL=60;
 public static function endpoint(string $slug):?array{$t=microtime(true);$r=RedisService::connect();self::$endpointRedisConnectMs=(microtime(true)-$t)*1000;$rk='lumen:ep:'.hash('sha256',$slug);if($r){try{$t=microtime(true);$v=$r->get($rk);self::$endpointRedisGetMs=(microtime(true)-$t)*1000;if(is_string($v)&&$v!==''){if($v==='!')return null;$x=json_decode($v,true);if(is_array($x))return$x;}}catch(\Throwable $e){}}$x=Db::name('endpoints')->where('slug',$slug)->where('status',1)->find();if($r){try{$r->setex($rk,self::EP_TTL,$x?json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES):'!');}catch(\Throwable $e){}}return$x?:null;}
 public static function endpointParams(int $endpointId):array{$r=RedisService::connect();$rk='lumen:ep_params:'.$endpointId;if($r){try{$v=$r->get($rk);if(is_string($v)&&$v!==''){$x=json_decode($v,true);if(is_array($x))return$x;}}catch(\Throwable $e){}}$x=Db::name('endpoint_params')->where('endpoint_id',$endpointId)->order('sort_order,id')->select()->toArray();if($r)try{$r->setex($rk,self::EP_TTL,json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}catch(\Throwable $e){}return$x;}
 public static function forgetEndpointParams(int $endpointId):void{$r=RedisService::connect();if($r)try{$r->del('lumen:ep_params:'.$endpointId);}catch(\Throwable $e){}}
 public static function auth(string $token):?array{$hash=hash('sha256',$token);$r=RedisService::connect();$rk='lumen:auth:'.$hash;if($r){try{$v=$r->get($rk);if(is_string($v)&&$v!==''){if($v==='!')return null;$x=json_decode($v,true);if(is_array($x))return$x;}}catch(\Throwable $e){}}$k=Db::name('keys')->where('key_hash',$hash)->where('status',1)->find();if(!$k){if($r)try{$r->setex($rk,15,'!');}catch(\Throwable $e){}return null;}$owner=null;$admin=null;if(!empty($k['user_id']))$owner=Db::name('users')->where('id',$k['user_id'])->find();if(!empty($k['admin_id']))$admin=Db::name('admins')->where('id',$k['admin_id'])->where('status',1)->find();$x=['key'=>$k,'owner'=>$owner,'admin'=>$admin];if($r)try{$r->setex($rk,self::AUTH_TTL,json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));}catch(\Throwable $e){}return$x;}
 public static function forgetEndpoint(string $slug):void{$r=RedisService::connect();if($r)try{$r->del('lumen:ep:'.hash('sha256',$slug));}catch(\Throwable $e){}}
 public static function forgetKeyHash(string $hash):void{$r=RedisService::connect();if($r)try{$r->del('lumen:auth:'.$hash);}catch(\Throwable $e){}}
 public static function forgetUser(int $uid):void{$r=RedisService::connect();if(!$r)return;try{$it=null;while(($keys=$r->scan($it,'lumen:auth:*',200))!==false){foreach($keys as $rk){$v=$r->get($rk);if(!$v||$v==='!')continue;$x=json_decode($v,true);if((int)($x['key']['user_id']??0)===$uid)$r->del($rk);}}}catch(\Throwable $e){}}
}
